function checkMaxLength(textareaID, maxLength) {
    currentLengthInTextarea = jQuery("#" + textareaID).val().length;
    jQuery(remainingLengthTempId).text(parseInt(maxLength) - parseInt(currentLengthInTextarea));

    if (currentLengthInTextarea > (maxLength)) {
        jQuery("textarea#comment").val(jQuery("textarea#comment").val().slice(0, maxLength));
        jQuery(remainingLengthTempId).text(0);
    }
}


var getUrlParameterYY1 = function getUrlParameter(sParam) {
    var sPageURL = window.location.search.substring(1),
        sURLVariables = sPageURL.split('&'),
        sParameterName,
        i;

    for (i = 0; i < sURLVariables.length; i++) {
        sParameterName = sURLVariables[i].split('=');

        if (sParameterName[0] === sParam) {
            return sParameterName[1] === undefined ? true : decodeURIComponent(sParameterName[1]);
        }
    }
};

function containsWordYY1(haystack, needle) {
    return (" " + haystack + " ").indexOf(" " + needle + " ") !== -1;
}
